    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=0):
        try:
            return int(v)
        except Exception:
            return default

    def get_xy(item):
        if isinstance(item, dict):
            return [pos(item.get("x", 0)), pos(item.get("y", 0))]
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            return [pos(item[0]), pos(item[1])]
        return None

    def step_toward(src, dst):
        dx = sgn(dst[0] - src[0])
        dy = sgn(dst[1] - src[1])
        return [dx, dy]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position", [0, 0])
    opp_pos = observation.get("opponent_position", [0, 0])
