    ox, oy = pos(opp_pos[0]), pos(opp_pos[1])

    w = pos(observation.get("grid_width", observation.get("width", 0)))
    h = pos(observation.get("grid_height", observation.get("height", 0)))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward([sx, sy], [ox, oy])

        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        target = max(corners, key=lambda c: manhattan(c, [ox, oy]))
        return step_toward([sx, sy], target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = None
        best_score = None
        for t in targets:
