            return step_toward([sx, sy], center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    best = None
    best_score = None
    for r in resources:
        xy = get_xy(r)
        if xy is None:
            continue
        score = manhattan([sx, sy], xy)
        if best is None or score < best_score:
            best = xy
            best_score = score
    if best is not None:
        return step_toward([sx, sy], best)

    if w and h:
        center = [w // 2, h // 2]
        away = [sx + sgn(sx - ox), sy + sgn(sy - oy)]
        if manhattan([sx, sy], center) > manhattan([sx, sy], away):
            return step_toward([sx, sy], center)
        return step_toward([sx, sy], away)

